import copy
import json
import os
import random
import re
import time

import requests

from dailycheckin import CheckIn


class MiMotion(CheckIn):
    name = "小米运动"

    def __init__(self, check_item):
        self.check_item = check_item
        # 运行前的账号快照, 用于在 config.json 中按索引定位当前账号
        self._check_item_snapshot = copy.deepcopy(check_item)
        self.headers = {
            "Content-Type": "application/x-www-form-urlencoded; charset=UTF-8",
            "User-Agent": "MiFit/6.12.0 (MCE16; Android 16; Density/1.5)",
            "app_name": "com.xiaomi.hm.health",
        }

    def get_time(self):
        try:
            url = "https://acs.m.taobao.com/gw/mtop.common.getTimestamp/"
            response = requests.get(url, headers=self.headers, timeout=10).json()
            t = response["data"]["t"]
            return t
        except Exception as e:
            print("时间戳获取失败，使用本地时间", e)
            return str(int(time.time() * 1000))

    def login(self, phone, password):
        phone_pattern = r"(^(1)\d{10}$)"
        if re.match(phone_pattern, phone):
            user = f"+86{phone}"
            third_name = "huami_phone"
        else:
            user = phone
            third_name = "huami"

        url1 = "https://api-user.zepp.com/registrations/" + user + "/tokens"
        data1 = f"client_id=HuaMi&country_code=CN&json_response=true&name={user}&password={password}&redirect_uri=https://s3-us-west-2.amazonaws.com/hm-registration/successsignin.html&state=REDIRECTION&token=access"

        try:
            r1 = requests.post(url1, data=data1, headers=self.headers, timeout=10)
            if r1.status_code == 429:
                return 0, 0, "请求过于频繁，请变换IP后再试"

            r1 = r1.json()
            code = r1["access"]
        except Exception as e:
            print("登录失败:", e)
            return 0, 0, "登录失败"

        url2 = "https://account.zepp.com/v2/client/login"
        data2 = f"app_name=com.xiaomi.hm.health&country_code=CN&code={code}&device_id=fuck1069-2002-7869-0129-757geoi6sam1&device_model=android_phone&app_version=6.12.0&grant_type=access_token&allow_registration=false&dn=account.zepp.com,api-user.zepp.com,api-mifit.zepp.com,api-watch.zepp.com,app-analytics.zepp.com,api-analytics.huami.com,auth.zepp.com&source=com.xiaomi.hm.health&third_name={third_name}"

        try:
            r2 = requests.post(url=url2, data=data2, headers=self.headers, timeout=10).json()
            login_token = r2["token_info"]["login_token"]
            userid = r2["token_info"]["user_id"]
            app_token = r2["token_info"]["app_token"]
            return login_token, userid, app_token
        except Exception as e:
            print("获取token失败:", e)
            return 0, 0, "获取token失败"

    def _build_msg(self, phone, step, response):
        message = "提交步数失败"
        if response is not None:
            try:
                message = response.json()["message"]
            except Exception:
                pass
        msg = [
            {"name": "帐号信息", "value": f"{phone[:4]}****{phone[-4:]}"},
            {"name": "修改信息", "value": f"{message}"},
            {"name": "修改步数", "value": f"{step}"},
        ]
        return "\n".join([f"{one.get('name')}: {one.get('value')}" for one in msg])

    @staticmethod
    def _token_invalid(response):
        """判断提交步数的响应是否表明 app_token 已失效(401/token 相关错误码)。"""
        if response is None:
            return False
        if response.status_code == 401:
            return True
        try:
            result = response.json()
        except ValueError:
            return False
        if not isinstance(result, dict):
            return False
        if str(result.get("code", "")) == "401":
            return True
        return "token" in str(result.get("message", "")).lower()

    @staticmethod
    def _find_config_path():
        # 与 dailycheckin/main.py 的配置查找顺序保持一致
        for one_path in [
            "/ql/scripts/config.json",
            "config.json",
            "../config.json",
            "./config/config.json",
            "../config/config.json",
            "/config.json",
        ]:
            path = os.path.join(os.getcwd(), one_path)
            if os.path.exists(path):
                return os.path.normpath(path)
        return None

    def _write_back_token(self, app_token, userid):
        """把登录获取的 app_token/user_id 原子写回 config.json 中的当前账号, 供下次运行复用。"""
        config_path = self._find_config_path()
        if not config_path:
            return
        try:
            with open(config_path, encoding="utf-8") as f:
                data = json.load(f)
        except (OSError, ValueError) as e:
            print(f"写回 app_token 失败: 读取 config.json 出错: {e}")
            return
        if not isinstance(data, dict):
            print("写回 app_token 失败: config.json 结构异常, 跳过写回")
            return
        accounts = next(
            (value for key, value in data.items() if key.upper() == "MIMOTION" and isinstance(value, list)),
            None,
        )
        if accounts is None:
            return
        # 按账号在配置列表中的索引匹配（对比运行前快照），匹配不到说明配置已被改动
        index = next((i for i, item in enumerate(accounts) if item == self._check_item_snapshot), None)
        if index is None:
            print("写回 app_token 失败: config.json 中未匹配到当前账号（配置可能已被修改）, 跳过写回")
            return
        accounts[index]["app_token"] = app_token
        accounts[index]["user_id"] = str(userid)
        # 安全写入：临时文件 + os.replace 原子替换；失败保留原文件并打印警告
        temp_path = f"{config_path}.tmp"
        try:
            with open(temp_path, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=4)
                f.write("\n")
                f.flush()
                os.fsync(f.fileno())
            os.replace(temp_path, config_path)
            print("已将 app_token 写回 config.json")
        except Exception as e:
            print(f"写回 app_token 失败: {e}")
            try:
                if os.path.exists(temp_path):
                    os.remove(temp_path)
            except OSError:
                pass

    def main(self):
        phone = str(self.check_item.get("phone"))
        password = str(self.check_item.get("password"))
        try:
            min_step = int(self.check_item.get("min_step", 10000))
        except Exception as e:
            print("初始化步数失败: 已将最小值设置为 10000", e)
            min_step = 10000
        try:
            max_step = int(self.check_item.get("max_step", 19999))
        except Exception as e:
            print("初始化步数失败: 已将最大值设置为 19999", e)
            max_step = 19999

        step = str(random.randint(min_step, max_step))

        # 复用配置中的 app_token（account.zepp.com/v2/client/login 返回）直接提交步数,
        # 跳过两步登录, 避免单 IP 登录限流（429）; token 失效再走完整登录换新
        saved_app_token = str(self.check_item.get("app_token") or "").strip()
        saved_user_id = str(self.check_item.get("user_id") or "").strip()
        if saved_app_token and saved_user_id:
            response = self.upload_step(saved_user_id, saved_app_token, step)
            if response is not None and not self._token_invalid(response):
                return self._build_msg(phone, step, response)
            if response is not None:
                print("配置中的 app_token 已失效，重新登录获取新 token")

        login_token, userid, app_token = self.login(phone, password)
        if login_token == 0:
            msg = [
                {"name": "帐号信息", "value": f"{phone[:4]}****{phone[-4:]}"},
                {"name": "修改信息", "value": "登陆失败"},
            ]
            return "\n".join([f"{one.get('name')}: {one.get('value')}" for one in msg])

        # 登录成功，把新的 app_token/user_id 安全写回 config.json 供下次运行复用
        self._write_back_token(app_token, userid)
        return self._build_msg(phone, step, self.upload_step(userid, app_token, step))

    def upload_step(self, userid, app_token, step):
        """提交步数。返回 Response; 网络异常返回 None, 由调用方决定后续动作。"""
        t = self.get_time()
        today = time.strftime("%F")
